routerAdd('GET','/api/pfriends/point-actions',(e)=>{ if(!e.auth) throw new ForbiddenError('Sesi diperlukan.'); const u=require(`${__hooks}/point-action-utils.js`); const isStaff=['ADMIN','VERIFIER'].includes(e.auth.getString('role')); const rows=e.app.findRecordsByFilter('point_actions',isStaff?'':'status = "ACTIVE"','actionClass,label',0,0); return e.json(200,{actions:rows.map(u.dto)}); },$apis.requireAuth('users'));
routerAdd('POST','/api/pfriends/staff/point-actions',(e)=>{ const u=require(`${__hooks}/point-action-utils.js`);u.staff(e);const body=new DynamicModel({label:'',description:'',actionClass:'C',pillar:'',points:1,dailyCap:1,status:'ACTIVE'});e.bindBody(body);const label=String(body.label||'').trim(),description=String(body.description||'').trim(),pillar=String(body.pillar||'').trim();if(label.length<3||description.length<10||pillar.length<3)throw new BadRequestError('Nama, deskripsi, dan pilar aksi belum lengkap.');if(!['B','C','D'].includes(body.actionClass))throw new BadRequestError('Aksi berbukti harus memakai kelas B, C, atau D.');const now=new Date().toISOString(),row=new Record(e.app.findCollectionByNameOrId('point_actions'));row.set('code',u.code(label));row.set('label',label);row.set('description',description);row.set('actionClass',body.actionClass);row.set('pillar',pillar);row.set('points',Math.max(1,Math.min(999,Number(body.points)||1)));row.set('dailyCap',Math.max(1,Math.min(100,Number(body.dailyCap)||1)));row.set('status',body.status==='INACTIVE'?'INACTIVE':'ACTIVE');row.set('workflow','EVIDENCE');row.set('isCore',false);row.set('createdBy',e.auth.id);row.set('updatedBy',e.auth.id);row.set('createdAt',now);row.set('updatedAt',now);e.app.save(row);u.audit(e.app,row,e.auth,'CREATE',null,u.dto(row));return e.json(201,u.dto(row));},$apis.requireAuth('users'));
routerAdd('PATCH','/api/pfriends/staff/point-actions/{id}',(e)=>{const u=require(`${__hooks}/point-action-utils.js`);u.staff(e);const row=e.app.findRecordById('point_actions',e.request.pathValue('id')),before=u.dto(row),body=new DynamicModel({label:before.label,description:before.description,actionClass:before.actionClass,pillar:before.pillar,points:before.points,dailyCap:before.dailyCap,status:before.status});e.bindBody(body);if(String(body.label).trim().length<3||String(body.description).trim().length<10||String(body.pillar).trim().length<3)throw new BadRequestError('Nama, deskripsi, dan pilar aksi belum lengkap.');row.set('label',String(body.label).trim());row.set('description',String(body.description).trim());row.set('actionClass',body.actionClass);row.set('pillar',String(body.pillar).trim());row.set('points',Math.max(1,Math.min(999,Number(body.points)||1)));row.set('dailyCap',Math.max(1,Math.min(100,Number(body.dailyCap)||1)));row.set('status',body.status==='INACTIVE'?'INACTIVE':'ACTIVE');row.set('updatedBy',e.auth.id);row.set('updatedAt',new Date().toISOString());e.app.save(row);u.audit(e.app,row,e.auth,'UPDATE',before,u.dto(row));return e.json(200,u.dto(row));},$apis.requireAuth('users'));
routerAdd('DELETE','/api/pfriends/staff/point-actions/{id}',(e)=>{const u=require(`${__hooks}/point-action-utils.js`);u.staff(e);const row=e.app.findRecordById('point_actions',e.request.pathValue('id')),before=u.dto(row);let used=false;try{used=e.app.findRecordsByFilter('verified_point_activities','pointAction={:id}','',1,0,{id:row.id}).length>0}catch(_){}try{used=used||e.app.findRecordsByFilter('activity_submissions','pointAction={:id}','',1,0,{id:row.id}).length>0}catch(_){}if(row.getBool('isCore')||used){row.set('status','INACTIVE');row.set('updatedBy',e.auth.id);row.set('updatedAt',new Date().toISOString());e.app.save(row);u.audit(e.app,row,e.auth,'ARCHIVE',before,u.dto(row));return e.json(200,{archived:true});}u.audit(e.app,row,e.auth,'DELETE',before,null);e.app.delete(row);return e.json(200,{archived:false});},$apis.requireAuth('users'));
routerAdd('GET','/api/pfriends/staff/point-actions/{id}/audit',(e)=>{const u=require(`${__hooks}/point-action-utils.js`);u.staff(e);const action=e.app.findRecordById('point_actions',e.request.pathValue('id'));const rows=e.app.findRecordsByFilter('point_action_audits','actionCode={:code}','-occurredAt',0,0,{code:action.getString('code')});return e.json(200,{audits:rows.map(r=>({id:r.id,operation:r.getString('operation'),actorName:r.getString('actorName'),actorRole:r.getString('actorRole'),before:r.get('before'),after:r.get('after'),occurredAt:r.getString('occurredAt')}))});},$apis.requireAuth('users'));
